import{prepareS8Hub,isS8SimulationProvider}from'./provider.mjs';
import{createSimulationMapAdapter}from'../ground_contact_r2/map-adapter.mjs';
export async function loadSelectedS8R2Adapter(signal){const p=await prepareS8Hub({state:'CLOSED',signal});try{if(!isS8SimulationProvider(p)||p.identity.revision!=='NEW_S8_GROUND_CONTACT_R1')throw Error('SIM_S8_CONTACT_REQUIRED');return createSimulationMapAdapter({provider:p,sourceKind:'NEW_REBUILD_LEAF_PROVIDER',expected:{mapId:'world:hub:S8',state:'CLOSED',width:3840,height:1728,imageSHA256:'f602c93bdee4c4bd7d08f87d9951b34515d9ffbb34769aea28a4331ffb8b5e06',supportSHA256:'617a378432d8c7ac710c767d370635b3f23ee6c9cfdae20cdbcad3728dce002d',footWidth:30,footHeight:8,contactPolicy:'NEW_COMMON_FOOT_IDLE30_DEPTH8'}})}catch(e){p.dispose();throw e}}
